// 1. Selección de elementos
const mainMap = document.querySelector('.map-svg > svg');
const detailContainer = document.getElementById('map-container');
const backButton = document.querySelector('.back-circle');
const regionLists = document.querySelectorAll('.regiones-lista');

// 2. Delegación de eventos para el mapa principal
if (mainMap) {
    mainMap.addEventListener('click', (e) => {
        // Buscamos el path clicado
        const targetPath = e.target.closest('.tooltip-target');

        if (targetPath) {
            // DETENEMOS el comportamiento por defecto (evita saltos de scroll)
            e.preventDefault();

            const regionName = targetPath.getAttribute('data-name');
            renderRegionDetail(regionName);
        }
    });
}

// 3. Función para mostrar el detalle
function renderRegionDetail(name) {
    const svgContent = MAP_DATA[name];

    if (svgContent) {
        // OCULTAR con lógica de colapso prevenida
        mainMap.style.display = 'none';
        regionLists.forEach(list => list.style.display = 'none');

        // RENDERIZAR contenido
        detailContainer.innerHTML = svgContent;
        detailContainer.style.display = 'block';

        if (backButton) backButton.style.display = 'flex';

        // ELIMINADO: window.scrollTo. Si quieres que la página no se mueva, 
        // no debes dar la orden de scroll.
    } else {
        console.error(`Error: No hay datos de SVG para la región: ${name}`);
    }
}

// 4. Función para volver al mapa general
function resetMap(e) {
    // Si la función es llamada por un evento de clic, detenemos el salto
    if (e && e.preventDefault) e.preventDefault();

    // MOSTRAR originales
    if (mainMap) mainMap.style.display = 'block';
    regionLists.forEach(list => list.style.display = 'flex');

    // LIMPIAR Y OCULTAR detalle
    if (detailContainer) {
        detailContainer.innerHTML = '';
        detailContainer.style.display = 'none';
    }

    if (backButton) backButton.style.display = 'none';
}

// 5. Vincular el botón de volver de forma segura
if (backButton) {
    // IMPORTANTE: Pasamos el objeto 'e' automáticamente
    backButton.addEventListener('click', resetMap);
}




/* ==========================================================================
   GESTIÓN DE TEMA (LIGHT/DARK MODE)
   ========================================================================== */
const themeToggle = document.getElementById('theme-toggle');
const body = document.body;

// 1. Cargar preferencia guardada de inmediato
const savedTheme = localStorage.getItem('theme');
if (savedTheme === 'light') {
    body.classList.add('light-mode');
}

// 2. Escuchar el click una sola vez
themeToggle.addEventListener('click', () => {
    // Alternar la clase
    body.classList.toggle('light-mode');
    
    // Guardar la preferencia actual
    const isLight = body.classList.contains('light-mode');
    localStorage.setItem('theme', isLight ? 'light' : 'dark');
});